import math
    import random
    import time

    LANGUAGE_WRAPPER = 'On a circular track of total angular measure 360 degrees, there are {alpha} distinct observers at distinct polar angles. An observer i can see observer j if and only if the smaller central angular separation between i and j is at most {delta_deg} degrees. In addition, a density rule is enforced: any (closed) arc of length {lambda_deg} degrees contains at most {mu} observers. For i = 1, 2, ..., {alpha}, let a_i be the number of other observers that observer i can see. Subject to the density rule, determine the maximum possible value of the sum a_1 + a_2 + ... + a_{alpha}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate parameters satisfying:
# - lambda_deg in {60, 72, 90, 120}
# - delta_deg = lambda_deg (tight case)
# - mu >= 3
# - Choose K in [2, floor(360/lambda_deg)-1] (number of full saturated clusters)
# - Choose r in [1, mu-1] (nontrivial remainder cluster)
# - alpha = K*mu + r
# These ensure feasibility: K*lambda_deg <= 360 and no arc of length lambda_deg contains more than mu points.
candidates_lambda = [60, 72, 90, 120]
max_tries = 1000
for _ in range(max_tries):
    lambda_deg = rng.choice(candidates_lambda)
    c = 360 // lambda_deg  # maximum number of disjoint lambda_deg-arcs around circle
    if c < 3:
        continue
    mu = rng.randint(3, 12)
    # Choose K within feasible range
    K_lo = 2
    K_hi = c - 1
    if K_hi < K_lo:
        continue
    K = rng.randint(K_lo, K_hi)
    # Choose remainder r to ensure nontrivial leftover cluster
    r = rng.randint(1, mu - 1) if mu > 1 else 0
    if r <= 0:
        continue
    alpha = K * mu + r
    # Set delta_deg equal to lambda_deg for the extremal case we prove
    delta_deg = lambda_deg
    # Final sanity checks
    if alpha >= 6 and K >= 2 and K <= c - 1 and 1 <= r <= mu - 1:
        return {
            'alpha': alpha,
            'delta_deg': delta_deg,
            'lambda_deg': lambda_deg,
            'mu': mu
        }
# Fallback deterministic assignment if random generation fails
lambda_deg = 90
mu = 5
c = 360 // lambda_deg
K = 2
r = 3
alpha = K * mu + r
return {
    'alpha': alpha,
    'delta_deg': lambda_deg,
    'lambda_deg': lambda_deg,
    'mu': mu
}

    def verifier(assign):
# Validate and compute the answer using the extremal packing argument:
# With delta_deg == lambda_deg, the maximum is achieved by packing floor(alpha/mu) saturated cliques (size mu)
# into disjoint lambda_deg-arcs and one leftover clique of size r = alpha % mu, separated so that no lambda_deg-arc
# contains points from more than one clique. Each clique contributes all internal ordered pairs; cross-clique pairs are forbidden by separation.
try:
    alpha = int(assign.get('alpha', None))
    delta_deg = int(assign.get('delta_deg', None))
    lambda_deg = int(assign.get('lambda_deg', None))
    mu = int(assign.get('mu', None))
except Exception:
    # Missing or bad types
    return (False, None)
# Basic domain checks
if alpha <= 0 or delta_deg <= 0 or lambda_deg <= 0 or mu <= 0:
    # invalid nonpositive parameters
    return (False, None)
# Tight case enforced: delta == lambda for the proof and computation
if delta_deg != lambda_deg:
    # We only validate instances with delta == lambda to ensure correctness
    return (False, None)
# Must allow at least two saturated clusters and a nontrivial remainder for difficulty
c = 360 // lambda_deg
K = alpha // mu
r = alpha % mu
if c < 3:
    # Not enough arcs to make this nontrivial
    return (False, None)
# Difficulty and feasibility constraints
if not (K >= 2 and K <= c - 1):
    # Not enough full clusters or too many to fit
    return (False, None)
if not (1 <= r <= mu - 1):
    # Need a nontrivial remainder cluster
    return (False, None)
# Compute maximum sum of a_i: each clique of size s contributes s*(s-1) ordered pairs; sum over cliques.
answer = K * mu * (mu - 1) + r * (r - 1)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

